use std::collections::HashMap;

fn group_by_length<'a>(words: &[&'a str]) -> HashMap<usize, Vec<&'a str>> {
    let mut map = HashMap::new();
    for &word in words {
        map.entry(word.len()).or_insert_with(Vec::new).push(word);
