struct TreeNode {
    val: i32,
    left: Option<Box<TreeNode>>,
    right: Option<Box<TreeNode>>,
}

impl TreeNode {
    fn new(val: i32) -> Self {
        TreeNode { val, left: None, right: None }
    }
    fn insert(&mut self, new_val: i32) {
        if new_val < self.val {
            match self.left {
                Some(ref mut node) => node.insert(new_val),
                None => self.left = Some(Box::new(TreeNode::new(new_val))),
            }
        } else {
            match self.right {
                Some(ref mut node) => node.insert(new_val),
                None => self.right = Some(Box::new(TreeNode::new(new_val))),
            }
        }
    }
}

fn main() {
    let mut tree = TreeNode::new(10);
    tree.insert(5);
    tree.insert(15);
    assert_eq!(tree.left.unwrap().val, 5);
    assert_eq!(tree.right.unwrap().val, 15);
    println!("✔ Recursive Boxed TreeNode works!");
}

