trait SimpleFuture {
    type Output;
    fn poll(&mut self) -> Result<Self::Output, ()>;
}

struct DelayFuture {
    ticks_remaining: usize,
}

impl SimpleFuture for DelayFuture {
    type Output = &'static str;
    fn poll(&mut self) -> Result<Self::Output, ()> {
        if self.ticks_remaining == 0 {
            Ok("Task Completed!")
        } else {
            self.ticks_remaining -= 1;
            Err(())
        }
    }
}

fn main() {
    let mut fut = DelayFuture { ticks_remaining: 3 };
    while let Err(()) = fut.poll() {
        println!("Polling future... Status: Pending");
    }
    println!("Future Resolved: {}", fut.poll().unwrap());
}

