fn safe_swap<T>(a: &mut T, b: &mut T) {
    unsafe {
        let mut temp = std::mem::MaybeUninit::<T>::uninit();
        std::ptr::copy_nonoverlapping(a, temp.as_mut_ptr(), 1);
        std::ptr::copy_nonoverlapping(b, a, 1);
        std::ptr::copy_nonoverlapping(temp.as_ptr(), b, 1);
    }
}

fn main() {
    let mut x = 100;
    let mut y = 200;
    safe_swap(&mut x, &mut y);
    assert_eq!(x, 200);
    assert_eq!(y, 100);
    println!("✔ Safe swap using raw pointer copy passed!");
}

