use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let queue = Arc::new(Mutex::new(vec![1, 2, 3, 4, 5, 6]));
    let results = Arc::new(Mutex::new(vec![]));
    let mut handles = vec![];

    for _ in 0..3 {
        let q = Arc::clone(&queue);
        let res = Arc::clone(&results);
        let h = thread::spawn(move || {
            loop {
                let task = {
                    let mut lock = q.lock().unwrap();
                    lock.pop()
                };
                match task {
                    Some(val) => {
                        res.lock().unwrap().push(val * 10);
                    }
                    None => break,
                }
            }
        });
        handles.push(h);
    }

    for h in handles {
        h.join().unwrap();
    }

    let mut final_results = results.lock().unwrap().clone();
    final_results.sort();
    assert_eq!(final_results, vec![10, 20, 30, 40, 50, 60]);
    println!("✔ ThreadPool worker queue drill passed successfully!");
}
